import React, { useEffect, useMemo, useState } from "react";
import { Box, Stack, Typography, IconButton, Button } from "@mui/material";
import { MagnifyingGlass, Plus, UsersThree } from "phosphor-react";
import { alpha, useTheme } from "@mui/material/styles";
import ChatElement from "../../components/ChatElement";
import { Search, SearchIconWrapper, StyledInputBase } from "../../components/Search";
import CreateGroup from "../../sections/main/CreateGroup";
import { useDispatch, useSelector } from "react-redux";
import { FetchGroupConversations } from "../../redux/slices/conversation";
import ChatComponent from "./Conversation";
import GroupInfo from "../../sections/main/GroupInfo";
import useResponsive from "../../hooks/useResponsive";
import BottomNav from "../../layouts/dashboard/BottomNav";
import EmptyConversation from "../../components/EmptyConversation";

const Group = () => {
  const dispatch = useDispatch();
  const theme = useTheme();
  const isDesktop = useResponsive("up", "md");
  const { room_id, chat_type, sideBar } = useSelector((state) => state.app);
  const { conversations } = useSelector((state) => state.conversation.group_chat);
  const [openDialog, setOpenDialog] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    dispatch(FetchGroupConversations());
  }, [dispatch]);

  const filtered = useMemo(() => {
    const query = searchTerm.trim().toLowerCase();
    return (conversations || []).filter((item) => !query || (item.name || "").toLowerCase().includes(query));
  }, [conversations, searchTerm]);

  const selected = chat_type === "group" && Boolean(room_id);

  return (
    <>
      <Stack direction="row" sx={{ width: "100%", minWidth: 0 }}>
        {(isDesktop || !selected) && (
          <Box
            component="aside"
            sx={{
              position: "relative",
              zIndex: 3,
              height: "100vh",
              width: isDesktop ? 368 : "100vw",
              flexShrink: 0,
              bgcolor: alpha(theme.palette.background.paper, 0.84),
              backdropFilter: "blur(22px)",
              borderRight: isDesktop ? `1px solid ${alpha(theme.palette.text.primary, 0.08)}` : 0,
            }}
          >
            {!isDesktop && <BottomNav />}
            <Stack height="100%" sx={{ pb: isDesktop ? 0 : 11 }}>
              <Stack px={3} pt={3} pb={2.25} spacing={2.25}>
                <Stack direction="row" alignItems="center" justifyContent="space-between">
                  <Stack spacing={0.25}>
                    <Typography variant="h4" sx={{ fontSize: 26 }}>Groups</Typography>
                    <Typography variant="caption" color="text.secondary">Shared spaces for your people</Typography>
                  </Stack>
                  <IconButton
                    aria-label="Create group"
                    onClick={() => setOpenDialog(true)}
                    sx={{ width: 44, height: 44, color: "white", background: "linear-gradient(135deg, #5C86FF, #7557E8)", boxShadow: "0 9px 22px rgba(79,124,255,.28)" }}
                  >
                    <Plus size={20} weight="bold" />
                  </IconButton>
                </Stack>
                <Search sx={{ height: 48, borderRadius: "15px", bgcolor: alpha(theme.palette.text.primary, 0.045), border: `1px solid ${alpha(theme.palette.text.primary, 0.07)}` }}>
                  <SearchIconWrapper><MagnifyingGlass size={19} color={theme.palette.text.secondary} /></SearchIconWrapper>
                  <StyledInputBase
                    placeholder="Search groups"
                    inputProps={{ "aria-label": "Search groups" }}
                    value={searchTerm}
                    onChange={(event) => setSearchTerm(event.target.value)}
                  />
                </Search>
                <Button startIcon={<Plus size={16} />} onClick={() => setOpenDialog(true)} sx={{ alignSelf: "flex-start", minHeight: 36, color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.08) }}>
                  New group
                </Button>
              </Stack>

              <Stack px={2} pb={2} spacing={0.4} sx={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
                {filtered.length ? filtered.map((item) => <ChatElement key={item.id} {...item} chat_type="group" />) : (
                  <Stack alignItems="center" justifyContent="center" spacing={1.5} sx={{ flex: 1, textAlign: "center", px: 4 }}>
                    <Box sx={{ width: 60, height: 60, borderRadius: "20px", display: "grid", placeItems: "center", bgcolor: alpha(theme.palette.primary.main, 0.1), color: "primary.main" }}>
                      <UsersThree size={28} />
                    </Box>
                    <Typography variant="subtitle2">No groups yet</Typography>
                    <Typography variant="caption" color="text.secondary">Create a space for a project, team, or close friends.</Typography>
                  </Stack>
                )}
              </Stack>
            </Stack>
          </Box>
        )}

        {(isDesktop || selected) && (
          <Box sx={{ height: "100vh", minWidth: 0, flex: 1, bgcolor: "background.default" }}>
            {selected ? <ChatComponent /> : <EmptyConversation type="group" />}
          </Box>
        )}
        {sideBar.open && sideBar.type === "GROUP" && <GroupInfo />}
      </Stack>
      {openDialog && <CreateGroup open={openDialog} handleClose={() => setOpenDialog(false)} />}
    </>
  );
};

export default Group;
