import {
  Avatar,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  IconButton,
  List,
  ListItem,
  ListItemAvatar,
  ListItemText,
  MenuItem,
  Stack,
  TextField,
  Tooltip,
  Typography,
  Chip,
} from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import {
  ArrowBendDownRight,
  CrownSimple,
  PencilSimple,
  Plus,
  Trash,
  UserMinus,
  UserPlus,
  X,
  SignOut,
} from "phosphor-react";
import React, { useCallback, useMemo, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  FetchFriends,
  SelectConversation,
  ToggleSidebar,
  UploadMedia,
} from "../../redux/slices/app";
import { UploadAvatar } from "../../components/upload";
import {
  AddMembersToGroup,
  LeaveGroupConversation,
  DeleteGroupConversation,
  RemoveMembersFromGroup,
  SetCurrentGroup,
  TransferGroupOwnership,
  UpdateGroupDetails,
} from "../../redux/slices/conversation";
import useResponsive from "../../hooks/useResponsive";
import { rightPanelHeaderSx, rightPanelSx } from "../../theme/rightPanel";

const GroupInfo = () => {
  const dispatch = useDispatch();
  const theme = useTheme();
  const isDesktop = useResponsive("up", "md");
  const userId = window.localStorage.getItem("user_id");

  const { friends } = useSelector((state) => state.app);
  const { current_group } = useSelector((state) => state.conversation.group_chat);

  const [editingMeta, setEditingMeta] = useState(false);
  const [nameInput, setNameInput] = useState(current_group?.name || "");
  const [avatarFile, setAvatarFile] = useState(current_group?.img || null);
  const [isSavingMeta, setIsSavingMeta] = useState(false);

  const [addOpen, setAddOpen] = useState(false);
  const [selectedToAdd, setSelectedToAdd] = useState([]);

  const [transferOpen, setTransferOpen] = useState(false);
  const [transferTo, setTransferTo] = useState("");

  const [leaveOpen, setLeaveOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);

  const isOwner = current_group?.owner_id === userId;
  const members = useMemo(() => current_group?.members || [], [current_group?.members]);

  React.useEffect(() => {
    dispatch(FetchFriends());
  }, [dispatch]);

  const memberIds = useMemo(() => new Set(members.map((m) => m.id?.toString())), [members]);

  const addableFriends = useMemo(() => {
    return (friends || []).filter((friend) => !memberIds.has(friend.id?.toString()));
  }, [friends, memberIds]);

  React.useEffect(() => {
    setNameInput(current_group?.name || "");
    setAvatarFile(current_group?.img || null);
    setEditingMeta(false);
    setSelectedToAdd([]);
    setTransferTo("");
  }, [current_group?.id, current_group?.name, current_group?.img]);

  const handleDropAvatar = useCallback((acceptedFiles) => {
    const file = acceptedFiles?.[0];
    if (!file) return;

    const fileWithPreview = Object.assign(file, {
      preview: URL.createObjectURL(file),
    });

    setAvatarFile(fileWithPreview);
  }, []);

  const resolveAvatarUrl = async () => {
    if (!avatarFile) return "";
    if (typeof avatarFile === "string") return avatarFile;

    const response = await dispatch(UploadMedia({ file: avatarFile }));
    return response?.data?.fileUrl || "";
  };

  const handleSaveMeta = async () => {
    if (!current_group?.id || !isOwner) return;

    try {
      setIsSavingMeta(true);
      const avatarUrl = await resolveAvatarUrl();

      const updated = await dispatch(
        UpdateGroupDetails({
          group_id: current_group.id,
          groupName: nameInput,
          groupAvatar: avatarUrl,
        })
      );

      if (updated?.id) {
        dispatch(SetCurrentGroup({ room_id: updated.id }));
        setEditingMeta(false);
      }
    } finally {
      setIsSavingMeta(false);
    }
  };

  const handleAddMembers = async () => {
    if (!current_group?.id || selectedToAdd.length === 0) return;
    const updated = await dispatch(
      AddMembersToGroup({
        group_id: current_group.id,
        members: selectedToAdd,
      })
    );
    if (updated?.id) {
      dispatch(SetCurrentGroup({ room_id: updated.id }));
      setSelectedToAdd([]);
      setAddOpen(false);
    }
  };

  const handleRemoveMember = async (memberId) => {
    if (!current_group?.id || !memberId) return;
    const updated = await dispatch(
      RemoveMembersFromGroup({
        group_id: current_group.id,
        members: [memberId],
      })
    );
    if (updated?.id) {
      dispatch(SetCurrentGroup({ room_id: updated.id }));
    }
  };

  const handleTransferOwnership = async () => {
    if (!current_group?.id || !transferTo) return;
    const updated = await dispatch(
      TransferGroupOwnership({
        group_id: current_group.id,
        newOwnerId: transferTo,
      })
    );
    if (updated?.id) {
      dispatch(SetCurrentGroup({ room_id: updated.id }));
      setTransferOpen(false);
      setTransferTo("");
    }
  };

  const handleLeaveGroup = async () => {
    if (!current_group?.id) return;
    const ok = await dispatch(LeaveGroupConversation({ group_id: current_group.id }));
    if (ok) {
      dispatch(SelectConversation({ room_id: null, chat_type: null }));
      setLeaveOpen(false);
      dispatch(ToggleSidebar());
    }
  };

  const handleDeleteGroup = async () => {
    if (!current_group?.id || !isOwner) return;
    const ok = await dispatch(DeleteGroupConversation({ group_id: current_group.id }));
    if (ok) {
      dispatch(SelectConversation({ room_id: null, chat_type: null }));
      setDeleteOpen(false);
      dispatch(ToggleSidebar());
    }
  };

  return (
    <Box sx={rightPanelSx(theme, isDesktop)}>
      <Stack spacing={2} sx={{ height: "100vh" }}>
        <Stack
          sx={rightPanelHeaderSx(theme)}
          alignItems={"center"}
          justifyContent="space-between"
          direction="row"
        >
          <Stack><Typography variant="h6">Group details</Typography><Typography variant="caption" color="text.secondary">Members and preferences</Typography></Stack>
          <IconButton onClick={() => dispatch(ToggleSidebar())}>
            <X />
          </IconButton>
        </Stack>

        <Stack px={3} spacing={2}>
          <Stack direction="row" spacing={2} alignItems="center">
            <Avatar src={current_group?.img} alt={current_group?.name} sx={{ width: 78, height: 78, bgcolor: alpha(theme.palette.primary.main, 0.12), color: "primary.main", fontSize: 25 }} />
            <Stack spacing={0.5} sx={{ minWidth: 0 }}>
              <Typography variant="subtitle1" noWrap>
                {current_group?.name || "Group"}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                {members.length} members
              </Typography>
              <Typography variant="caption" color="text.secondary">
                {isOwner ? "You are owner" : "Member"}
              </Typography>
            </Stack>
          </Stack>

          {isOwner && (
            <Stack direction="row" spacing={1}>
              <Button
                size="small"
                variant="outlined"
                startIcon={<PencilSimple size={16} />}
                onClick={() => setEditingMeta((prev) => !prev)}
              >
                {editingMeta ? "Close Edit" : "Edit Group"}
              </Button>
              <Button
                size="small"
                variant="outlined"
                startIcon={<UserPlus size={16} />}
                onClick={() => setAddOpen(true)}
              >
                Add Members
              </Button>
            </Stack>
          )}

          {editingMeta && (
            <Stack spacing={1.5}>
              <TextField
                size="small"
                label="Group name"
                value={nameInput}
                onChange={(e) => setNameInput(e.target.value)}
                inputProps={{ maxLength: 80 }}
              />
              <Stack spacing={1} alignItems="center" sx={{ py: 0.5 }}>
                <UploadAvatar
                  file={avatarFile}
                  onDrop={handleDropAvatar}
                  accept={{ "image/*": [] }}
                  maxSize={3145728}
                />
                <Typography variant="caption" color="text.secondary" textAlign="center">
                  Upload group photo (max 3MB)
                </Typography>
              </Stack>
              <Button
                variant="contained"
                onClick={handleSaveMeta}
                disabled={isSavingMeta || !nameInput.trim()}
              >
                Save Changes
              </Button>
            </Stack>
          )}

          <Divider />
        </Stack>

        <Stack px={3} spacing={1} sx={{ flexGrow: 1, overflowY: "auto" }}>
          <Typography variant="subtitle2">Members</Typography>
          <List dense disablePadding>
            {members.map((member) => {
              const memberId = member.id?.toString();
              const isMemberOwner = current_group?.owner_id?.toString() === memberId;
              const isSelf = memberId === userId;

              return (
                <ListItem
                  key={memberId}
                  sx={{ px: 0 }}
                  secondaryAction={
                    isOwner && !isMemberOwner && !isSelf ? (
                      <Tooltip title="Remove member">
                        <IconButton edge="end" onClick={() => handleRemoveMember(memberId)}>
                          <UserMinus size={18} />
                        </IconButton>
                      </Tooltip>
                    ) : null
                  }
                >
                  <ListItemAvatar>
                    <Avatar src={member.avatar} alt={`${member.firstName || ""} ${member.lastName || ""}`} />
                  </ListItemAvatar>
                  <ListItemText
                    primary={`${member.firstName || ""} ${member.lastName || ""}`.trim() || member.email}
                    secondary={
                      <Stack direction="row" spacing={1} alignItems="center">
                        <Typography variant="caption" color="text.secondary">
                          {member.email}
                        </Typography>
                        {isMemberOwner && (
                          <Chip
                            size="small"
                            icon={<CrownSimple size={12} />}
                            label="Owner"
                            sx={{ height: 20 }}
                          />
                        )}
                      </Stack>
                    }
                  />
                </ListItem>
              );
            })}
          </List>
        </Stack>

        <Stack px={3} pb={2} spacing={1}>
          {isOwner && members.length > 2 && (
            <Button
              variant="outlined"
              startIcon={<ArrowBendDownRight size={16} />}
              onClick={() => setTransferOpen(true)}
            >
              Transfer Ownership
            </Button>
          )}

          <Button
            color="error"
            variant="outlined"
            startIcon={<SignOut size={16} />}
            onClick={() => setLeaveOpen(true)}
            disabled={isOwner}
          >
            Leave Group
          </Button>
          {isOwner && (
            <Typography variant="caption" color="text.secondary">
              Owner must transfer ownership before leaving.
            </Typography>
          )}
          {isOwner && (
            <Button
              color="error"
              variant="contained"
              startIcon={<Trash size={16} />}
              onClick={() => setDeleteOpen(true)}
            >
              Delete Group
            </Button>
          )}
        </Stack>
      </Stack>

      <Dialog open={addOpen} onClose={() => setAddOpen(false)} fullWidth maxWidth="xs">
        <DialogTitle>Add Members</DialogTitle>
        <DialogContent>
          <TextField
            select
            fullWidth
            SelectProps={{
              multiple: true,
              value: selectedToAdd,
              onChange: (e) => {
                const next = e.target.value;
                setSelectedToAdd(Array.isArray(next) ? next : [next]);
              },
            }}
            helperText="Select one or more friends to add"
          >
            {addableFriends.map((friend) => (
              <MenuItem key={friend.id} value={friend.id?.toString()}>
                {`${friend.firstName || ""} ${friend.lastName || ""}`.trim() || friend.email}
              </MenuItem>
            ))}
          </TextField>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAddOpen(false)}>Cancel</Button>
          <Button
            onClick={handleAddMembers}
            variant="contained"
            startIcon={<Plus size={16} />}
            disabled={selectedToAdd.length === 0}
          >
            Add
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={transferOpen} onClose={() => setTransferOpen(false)} fullWidth maxWidth="xs">
        <DialogTitle>Transfer Ownership</DialogTitle>
        <DialogContent>
          <TextField
            select
            fullWidth
            value={transferTo}
            onChange={(e) => setTransferTo(e.target.value)}
            helperText="Choose a member to make new owner"
          >
            {members
              .filter((member) => member.id?.toString() !== current_group?.owner_id?.toString())
              .map((member) => (
                <MenuItem key={member.id} value={member.id?.toString()}>
                  {`${member.firstName || ""} ${member.lastName || ""}`.trim() || member.email}
                </MenuItem>
              ))}
          </TextField>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setTransferOpen(false)}>Cancel</Button>
          <Button onClick={handleTransferOwnership} variant="contained" disabled={!transferTo}>
            Transfer
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={leaveOpen} onClose={() => setLeaveOpen(false)}>
        <DialogTitle>Leave group?</DialogTitle>
        <DialogContent>
          <Typography variant="body2">Are you sure you want to leave this group?</Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setLeaveOpen(false)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleLeaveGroup}>
            Leave
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={deleteOpen} onClose={() => setDeleteOpen(false)}>
        <DialogTitle>Delete group?</DialogTitle>
        <DialogContent>
          <Typography variant="body2">
            This permanently deletes the group and its message history for every member.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteOpen(false)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDeleteGroup}>
            Delete Group
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default GroupInfo;
