import { alpha } from "@mui/material/styles";

export const RIGHT_PANEL_WIDTH = 370;
export const RIGHT_PANEL_HEADER_HEIGHT = 78;

export const rightPanelSx = (theme, isDesktop) => ({
  position: isDesktop ? "relative" : "absolute",
  inset: isDesktop ? "auto" : 0,
  zIndex: 8,
  width: isDesktop ? RIGHT_PANEL_WIDTH : "100vw",
  height: "100vh",
  flexShrink: 0,
  backgroundColor: alpha(theme.palette.background.paper, 0.96),
  backdropFilter: "blur(26px) saturate(150%)",
  borderLeft: `1px solid ${alpha(theme.palette.text.primary, 0.12)}`,
  boxShadow: theme.palette.mode === "light"
    ? "-18px 0 48px rgba(31,42,68,.12)"
    : "-18px 0 48px rgba(0,0,0,.32)",
});

export const rightPanelHeaderSx = (theme) => ({
  minHeight: RIGHT_PANEL_HEADER_HEIGHT,
  px: 2.25,
  borderBottom: `1px solid ${alpha(theme.palette.text.primary, 0.09)}`,
});
