import React, { useDeferredValue, useEffect, useMemo, useState } from "react";
import {
  Avatar,
  Box,
  Button,
  Checkbox,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  IconButton,
  InputAdornment,
  List,
  ListItemAvatar,
  ListItemButton,
  ListItemText,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { ArrowLeft, Check, MagnifyingGlass, UsersThree, X } from "phosphor-react";
import { useDispatch, useSelector } from "react-redux";
import { FetchFriends, SelectConversation } from "../../redux/slices/app";
import { CreateGroupConversation, SetCurrentGroup } from "../../redux/slices/conversation";
import useResponsive from "../../hooks/useResponsive";

const steps = ["Group details", "Choose members"];

const displayName = (member) => {
  const name = `${member?.firstName || ""} ${member?.lastName || ""}`.trim();
  return name || member?.email || "Unknown member";
};

const CreateGroup = ({ open, handleClose }) => {
  const theme = useTheme();
  const dispatch = useDispatch();
  const isDesktop = useResponsive("up", "sm");
  const { friends = [] } = useSelector((state) => state.app);
  const [step, setStep] = useState(0);
  const [name, setName] = useState("");
  const [nameTouched, setNameTouched] = useState(false);
  const [search, setSearch] = useState("");
  const deferredSearch = useDeferredValue(search.trim().toLowerCase());
  const [selectedIds, setSelectedIds] = useState([]);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    dispatch(FetchFriends());
  }, [dispatch]);

  const selectedMembers = useMemo(
    () => selectedIds.map((id) => friends.find((friend) => friend.id?.toString() === id)).filter(Boolean),
    [friends, selectedIds]
  );

  const visibleFriends = useMemo(() => {
    if (!deferredSearch) return friends;
    return friends.filter((friend) => `${displayName(friend)} ${friend.email || ""}`.toLowerCase().includes(deferredSearch));
  }, [deferredSearch, friends]);

  const cleanName = name.trim();
  const nameError = nameTouched && !cleanName ? "Give your group a name" : "";
  const canContinue = Boolean(cleanName) && cleanName.length <= 80;
  const canCreate = selectedIds.length >= 2 && !submitting;

  const toggleMember = (memberId) => {
    const id = memberId?.toString();
    if (!id) return;
    setSelectedIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  };

  const close = () => {
    if (submitting) return;
    handleClose();
  };

  const next = () => {
    setNameTouched(true);
    if (canContinue) setStep(1);
  };

  const create = async () => {
    if (!canCreate) return;
    try {
      setSubmitting(true);
      const group = await dispatch(CreateGroupConversation({ groupName: cleanName, members: selectedIds }));
      if (group?.id) {
        dispatch(SelectConversation({ room_id: group.id, chat_type: "group" }));
        dispatch(SetCurrentGroup({ room_id: group.id }));
        handleClose();
      }
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog
      open={open}
      onClose={close}
      fullWidth
      fullScreen={!isDesktop}
      maxWidth="sm"
      PaperProps={{ sx: { maxHeight: { sm: "min(760px, calc(100vh - 48px))" }, overflow: "hidden" } }}
    >
      <Stack sx={{ minHeight: { xs: "100%", sm: 650 } }}>
        <Stack
          direction="row"
          alignItems="center"
          justifyContent="space-between"
          sx={{ minHeight: 76, px: { xs: 2, sm: 3 }, borderBottom: `1px solid ${alpha(theme.palette.text.primary, 0.08)}` }}
        >
          <Stack direction="row" alignItems="center" spacing={1.5}>
            {step === 1 ? (
              <IconButton aria-label="Back to group details" onClick={() => setStep(0)}><ArrowLeft size={21} /></IconButton>
            ) : (
              <Box sx={{ width: 42, height: 42, borderRadius: "14px", display: "grid", placeItems: "center", color: "white", background: "linear-gradient(135deg, #628BFF, #7356E8)", boxShadow: "0 9px 22px rgba(79,124,255,.24)" }}>
                <UsersThree size={21} weight="duotone" />
              </Box>
            )}
            <Stack spacing={0.1}>
              <Typography variant="h6">Create a group</Typography>
              <Typography variant="caption" color="text.secondary">{steps[step]}</Typography>
            </Stack>
          </Stack>
          <IconButton aria-label="Close create group" onClick={close} disabled={submitting}><X size={21} /></IconButton>
        </Stack>

        <Stack direction="row" spacing={1} sx={{ px: { xs: 2, sm: 3 }, pt: 2.5 }}>
          {steps.map((label, index) => (
            <Stack key={label} direction="row" alignItems="center" spacing={0.75} sx={{ flex: 1 }}>
              <Box sx={{ width: 24, height: 24, flexShrink: 0, borderRadius: "50%", display: "grid", placeItems: "center", color: index <= step ? "white" : "text.secondary", bgcolor: index <= step ? "primary.main" : alpha(theme.palette.text.primary, 0.07), fontSize: 11, fontWeight: 800 }}>
                {index < step ? <Check size={13} weight="bold" /> : index + 1}
              </Box>
              <Typography variant="caption" noWrap sx={{ color: index <= step ? "text.primary" : "text.secondary", fontWeight: index === step ? 800 : 500 }}>{label}</Typography>
              {index === 0 && <Box sx={{ flex: 1, height: 2, minWidth: 12, borderRadius: 2, bgcolor: step > 0 ? "primary.main" : alpha(theme.palette.text.primary, 0.08) }} />}
            </Stack>
          ))}
        </Stack>

        <DialogContent sx={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0, px: { xs: 2, sm: 3 }, py: 3 }}>
          {step === 0 ? (
            <Stack spacing={3}>
              <Stack alignItems="center" spacing={1.5} sx={{ py: 2 }}>
                <Avatar sx={{ width: 92, height: 92, fontSize: 32, fontWeight: 800, color: "white", background: "linear-gradient(145deg, #6C92FF, #7356E8)", boxShadow: "0 18px 38px rgba(79,124,255,.24)" }}>
                  {cleanName ? cleanName.charAt(0).toUpperCase() : <UsersThree size={34} weight="duotone" />}
                </Avatar>
                <Stack spacing={0.25} alignItems="center">
                  <Typography variant="subtitle1" sx={{ fontWeight: 800 }}>{cleanName || "Your new group"}</Typography>
                  <Typography variant="caption" color="text.secondary">You can update the photo later</Typography>
                </Stack>
              </Stack>

              <TextField
                autoFocus
                fullWidth
                label="Group name"
                placeholder="Weekend plans, Product team..."
                value={name}
                onBlur={() => setNameTouched(true)}
                onChange={(event) => setName(event.target.value.slice(0, 80))}
                onKeyDown={(event) => { if (event.key === "Enter") next(); }}
                error={Boolean(nameError)}
                helperText={nameError || "Choose something everyone will recognize"}
                inputProps={{ maxLength: 80, "aria-describedby": "group-name-count" }}
                InputProps={{ endAdornment: <InputAdornment position="end"><Typography id="group-name-count" variant="caption" color={name.length > 72 ? "warning.main" : "text.secondary"}>{name.length}/80</Typography></InputAdornment> }}
              />

              <Box sx={{ p: 2, borderRadius: "16px", bgcolor: alpha(theme.palette.primary.main, 0.06), border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}` }}>
                <Typography variant="body2" sx={{ fontWeight: 700 }}>A group needs at least two other people</Typography>
                <Typography variant="caption" color="text.secondary">Only your existing friends can be added. You will become the group owner.</Typography>
              </Box>
            </Stack>
          ) : (
            <Stack spacing={2} flex={1} minHeight={0}>
              <TextField
                fullWidth
                autoFocus
                placeholder="Search friends"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                inputProps={{ "aria-label": "Search friends to add" }}
                InputProps={{ startAdornment: <InputAdornment position="start"><MagnifyingGlass size={19} /></InputAdornment> }}
              />

              <Stack direction="row" alignItems="center" justifyContent="space-between">
                <Typography variant="subtitle2">{selectedIds.length} selected</Typography>
                {selectedIds.length > 0 && <Button size="small" onClick={() => setSelectedIds([])} sx={{ minHeight: 32 }}>Clear</Button>}
              </Stack>

              {selectedMembers.length > 0 && (
                <Stack direction="row" spacing={1} sx={{ overflowX: "auto", pb: 0.5, flexShrink: 0 }}>
                  {selectedMembers.map((member) => (
                    <Chip
                      key={member.id}
                      avatar={<Avatar src={member.avatar}>{displayName(member).charAt(0)}</Avatar>}
                      label={displayName(member)}
                      onDelete={() => toggleMember(member.id)}
                      sx={{ flexShrink: 0, height: 36 }}
                    />
                  ))}
                </Stack>
              )}

              <Box sx={{ flex: 1, minHeight: 0, overflowY: "auto", borderRadius: "17px", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}` }}>
                {visibleFriends.length ? (
                  <List disablePadding aria-label="Friends">
                    {visibleFriends.map((member, index) => {
                      const id = member.id?.toString();
                      const selected = selectedIds.includes(id);
                      const online = member.status === "ONLINE";
                      return (
                        <ListItemButton
                          key={id}
                          selected={selected}
                          onClick={() => toggleMember(id)}
                          sx={{ minHeight: 68, px: 1.5, borderBottom: index < visibleFriends.length - 1 ? `1px solid ${alpha(theme.palette.text.primary, 0.06)}` : 0, "&.Mui-selected": { bgcolor: alpha(theme.palette.primary.main, 0.08) } }}
                        >
                          <ListItemAvatar sx={{ minWidth: 54 }}>
                            <Box sx={{ position: "relative", width: 42 }}>
                              <Avatar src={member.avatar} alt={displayName(member)} sx={{ width: 42, height: 42, bgcolor: alpha(theme.palette.primary.main, 0.12), color: "primary.main" }}>{displayName(member).charAt(0)}</Avatar>
                              {online && <Box sx={{ position: "absolute", width: 11, height: 11, right: 0, bottom: 0, borderRadius: "50%", bgcolor: "success.main", border: `2px solid ${theme.palette.background.paper}` }} />}
                            </Box>
                          </ListItemAvatar>
                          <ListItemText primary={displayName(member)} secondary={online ? "Active now" : member.email} primaryTypographyProps={{ variant: "subtitle2", noWrap: true }} secondaryTypographyProps={{ variant: "caption", noWrap: true, color: online ? "success.main" : "text.secondary" }} />
                          <Checkbox checked={selected} tabIndex={-1} disableRipple inputProps={{ "aria-label": `Add ${displayName(member)}` }} />
                        </ListItemButton>
                      );
                    })}
                  </List>
                ) : (
                  <Stack alignItems="center" justifyContent="center" spacing={1} sx={{ minHeight: 230, p: 3, textAlign: "center" }}>
                    <Box sx={{ width: 48, height: 48, borderRadius: "16px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.09) }}><UsersThree size={22} /></Box>
                    <Typography variant="subtitle2">{search ? "No friends found" : "No friends available"}</Typography>
                    <Typography variant="caption" color="text.secondary">{search ? "Try a different name or email." : "Add friends before creating a group."}</Typography>
                  </Stack>
                )}
              </Box>
            </Stack>
          )}
        </DialogContent>

        <DialogActions sx={{ minHeight: 76, px: { xs: 2, sm: 3 }, py: 1.5, borderTop: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, justifyContent: "space-between" }}>
          <Button color="inherit" onClick={step === 0 ? close : () => setStep(0)} disabled={submitting}>{step === 0 ? "Cancel" : "Back"}</Button>
          {step === 0 ? (
            <Button variant="contained" onClick={next} disabled={!canContinue}>Choose members</Button>
          ) : (
            <Stack alignItems="flex-end" spacing={0.35}>
              <Button variant="contained" onClick={create} disabled={!canCreate}>{submitting ? "Creating..." : `Create group${selectedIds.length ? ` (${selectedIds.length + 1})` : ""}`}</Button>
              {selectedIds.length < 2 && <Typography variant="caption" color="text.secondary">Select {2 - selectedIds.length} more</Typography>}
            </Stack>
          )}
        </DialogActions>
      </Stack>
    </Dialog>
  );
};

export default CreateGroup;
