import React from "react";
import { alpha, useTheme } from "@mui/material/styles";
import { Box, Stack, Typography } from "@mui/material";
import { Nav_Buttons, Nav_Setting } from "../../data";
import { useDispatch, useSelector } from "react-redux";
import { UpdateTab } from "../../redux/slices/app";
import { useNavigate } from "react-router-dom";

const paths = ["/app", "/group", "/call", "/settings"];

const BottomNav = () => {
  const theme = useTheme();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { tab } = useSelector((state) => state.app);
  const items = [...Nav_Buttons, ...Nav_Setting];

  const select = (index) => {
    dispatch(UpdateTab({ tab: index }));
    navigate(paths[index] || "/app");
  };

  return (
    <Box
      component="nav"
      aria-label="Mobile navigation"
      sx={{
        zIndex: 30,
        position: "fixed",
        left: 12,
        right: 12,
        bottom: 12,
        px: 1,
        pb: "env(safe-area-inset-bottom)",
        borderRadius: "22px",
        border: `1px solid ${alpha(theme.palette.text.primary, 0.1)}`,
        bgcolor: alpha(theme.palette.background.paper, 0.88),
        backdropFilter: "blur(24px) saturate(160%)",
        boxShadow: theme.palette.mode === "light" ? "0 16px 45px rgba(34,45,70,.18)" : "0 16px 45px rgba(0,0,0,.5)",
      }}
    >
      <Stack direction="row" alignItems="center" justifyContent="space-around" height={68}>
        {items.map((item) => {
          const active = item.index === tab;
          return (
            <Stack
              key={item.index}
              component="button"
              type="button"
              aria-label={item.title}
              aria-current={active ? "page" : undefined}
              onClick={() => select(item.index)}
              alignItems="center"
              justifyContent="center"
              spacing={0.25}
              sx={{
                minWidth: 58,
                height: 54,
                border: 0,
                borderRadius: "16px",
                color: active ? "primary.main" : "text.secondary",
                bgcolor: active ? alpha(theme.palette.primary.main, 0.11) : "transparent",
                cursor: "pointer",
                font: "inherit",
                "& svg": { width: 21, height: 21 },
              }}
            >
              {item.icon}
              <Typography sx={{ fontSize: 10, fontWeight: active ? 800 : 600 }}>{item.title}</Typography>
            </Stack>
          );
        })}
      </Stack>
    </Box>
  );
};

export default BottomNav;
