import React from "react";
import { Box, Button, Stack, Typography } from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { ChatCircleDots, UsersThree } from "phosphor-react";

const EmptyConversation = ({ type = "direct", onCompose }) => {
  const theme = useTheme();
  const isGroup = type === "group";
  const Icon = isGroup ? UsersThree : ChatCircleDots;

  return (
    <Stack alignItems="center" justifyContent="center" sx={{ width: "100%", height: "100%", p: 3, overflow: "hidden" }}>
      <Box sx={{ position: "relative", width: 230, height: 180, mb: 3 }}>
        <Box sx={{ position: "absolute", inset: 15, borderRadius: "50%", background: `radial-gradient(circle, ${alpha(theme.palette.primary.main, 0.18)}, transparent 68%)`, filter: "blur(2px)" }} />
        {[0, 1, 2].map((item) => (
          <Box key={item} sx={{ position: "absolute", left: 42 + item * 44, top: 60 - (item % 2) * 18, width: 72, height: 54, borderRadius: item % 2 ? "20px 20px 6px 20px" : "20px 20px 20px 6px", bgcolor: item === 1 ? "primary.main" : "background.paper", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, boxShadow: "0 14px 35px rgba(34,45,70,.12)", opacity: item === 2 ? 0.72 : 1 }} />
        ))}
        <Box sx={{ position: "absolute", left: "50%", bottom: 14, transform: "translateX(-50%)", width: 58, height: 58, borderRadius: "20px", display: "grid", placeItems: "center", bgcolor: "background.paper", color: "primary.main", boxShadow: "0 16px 38px rgba(34,45,70,.16)", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}` }}>
          <Icon size={27} weight="duotone" />
        </Box>
      </Box>
      <Typography variant="h5" textAlign="center">Your conversations, beautifully organized</Typography>
      <Typography variant="body2" color="text.secondary" textAlign="center" sx={{ maxWidth: 390, mt: 1, lineHeight: 1.7 }}>
        {isGroup ? "Choose a group to continue the conversation, or create a new shared space." : "Select a conversation from the sidebar to pick up where you left off."}
      </Typography>
      {onCompose && <Button variant="contained" onClick={onCompose} sx={{ mt: 3 }}>Start a conversation</Button>}
    </Stack>
  );
};

export default EmptyConversation;
